import { InsufficientStockError, InvalidQuantityError } from './errors';
import { Quantity } from './Quantity';

/**
 * A catalogue product and its stock. Units on hand stay in the warehouse
 * until shipped; reserved units are on hand but promised to open orders.
 */
export class Product {
  private constructor(
    readonly id: string,
    readonly name: string,
    private onHandUnits: number,
    private reservedUnits: number,
  ) {}

  static create(id: string, name: string, onHand: number): Product {
    if (!Number.isInteger(onHand) || onHand < 0) {
      throw new InvalidQuantityError(`Stock on hand must be a non-negative integer, got ${onHand}`);
    }
    return new Product(id, name, onHand, 0);
  }

  get onHand(): number {
    return this.onHandUnits;
  }

  get reserved(): number {
    return this.reservedUnits;
  }

  get available(): number {
    return this.onHandUnits - this.reservedUnits;
  }

  canReserve(quantity: Quantity): boolean {
    return quantity.value <= this.available;
  }

  reserve(quantity: Quantity): void {
    if (!this.canReserve(quantity)) {
      throw new InsufficientStockError(this.id, quantity.value, this.available);
    }
    this.reservedUnits += quantity.value;
  }

  release(quantity: Quantity): void {
    this.assertReserved(quantity);
    this.reservedUnits -= quantity.value;
  }

  /** Reserved units leave the warehouse. */
  dispatch(quantity: Quantity): void {
    this.assertReserved(quantity);
    this.reservedUnits -= quantity.value;
    this.onHandUnits -= quantity.value;
  }

  private assertReserved(quantity: Quantity): void {
    if (quantity.value > this.reservedUnits) {
      throw new InvalidQuantityError(
        `Cannot use ${quantity.value} reserved units of product ${this.id}; only ${this.reservedUnits} reserved`,
      );
    }
  }
}

